def body(p):
    out=[]
    if p.get('body',{}).get('data'):
        d=p['body']['data']; d+='='*(-len(d)%4)
        out.append(base64.urlsafe_b64decode(d).decode('utf-8','replace'))
    for c in p.get('parts',[]) or []: out+=body(c)
    return out
